<style>
:root{--surface:#fff;--surface-alt:#f8f9fd;--input-bg:#fff;--heading:#11152b;--shadow:0 12px 36px rgba(20,24,65,.06)}
html[data-theme="dark"]{color-scheme:dark;--primary:#9188ff;--primary-dark:#7769ec;--dark:#e9eaf5;--text:#c7cbe0;--muted:#a1a7bf;--border:#333b55;--bg:#111827;--white:#151d30;--surface:#1c2639;--surface-alt:#111827;--input-bg:#202c40;--heading:#f4f5ff;--shadow:0 12px 36px rgba(0,0,0,.16)}
body{background:var(--bg);color:var(--dark)}.site-header{background:var(--surface);border-color:var(--border)}.nav-links a{color:var(--text)}.brand{color:var(--dark)}
.btn-outline{background:var(--surface);color:var(--dark);border-color:var(--border)}.btn-outline:hover{background:var(--surface-alt)}.language-btn,.theme-btn{background:var(--surface-alt);border:1px solid var(--border);color:var(--primary);border-radius:9px;padding:9px 12px;cursor:pointer;font-size:13px;font-weight:700}.theme-btn{white-space:nowrap}
.card{max-width:920px;margin:45px auto;padding:32px;background:var(--surface);border:1px solid var(--border);border-radius:18px;box-shadow:var(--shadow)}.card.auth{max-width:440px}.title{font-size:clamp(25px,3vw,33px);margin-bottom:9px;letter-spacing:-.7px}.sub{color:var(--muted);line-height:1.65;margin-bottom:24px}.small{font-size:13px;color:var(--muted);line-height:1.6}.actions{display:flex;align-items:center;flex-wrap:wrap;gap:11px;margin:20px 0}.card label{font-size:13px;font-weight:700;display:block;margin:15px 0 7px}.card input,.card select,.authority-wrap input,.authority-wrap select{background:var(--input-bg);border:1px solid var(--border);color:var(--dark);border-radius:9px;padding:11px;width:100%;font:inherit;font-size:13px;min-width:0}.card form>.wide{width:100%;margin-top:19px}.card .hint{text-align:center;margin-top:19px;color:var(--muted);font-size:13px}.card .hint a{color:var(--primary)}.card .business{padding:17px 0;border-bottom:1px solid var(--border)}.card .business:last-child{border-bottom:0}
@media(max-width:550px){.card{margin:22px 12px;padding:21px}.theme-btn{padding:9px}.nav-actions{gap:6px}}
/* All existing public/registration pages inherit the same saved appearance. */
html[data-theme="dark"] .hero{background:radial-gradient(circle at 80% 10%,rgba(100,92,200,.15),transparent 35%),var(--bg)}
html[data-theme="dark"] .hero-label,html[data-theme="dark"] .preview-frame,html[data-theme="dark"] .preview-main,html[data-theme="dark"] .stat-card,html[data-theme="dark"] .chart-card,html[data-theme="dark"] .floating-card,html[data-theme="dark"] .trust-section,html[data-theme="dark"] .features-section,html[data-theme="dark"] .feature-card,html[data-theme="dark"] .process-card,html[data-theme="dark"] .about-section,html[data-theme="dark"] .about-box,html[data-theme="dark"] .cta-section,html[data-theme="dark"] .register-page{background:var(--surface);color:var(--dark)}
html[data-theme="dark"] .preview-sidebar,html[data-theme="dark"] .process-section,html[data-theme="dark"] .about-visual,html[data-theme="dark"] .side-item.active{background:var(--surface-alt)}
html[data-theme="dark"] .hero-description,html[data-theme="dark"] .hero-note,html[data-theme="dark"] .preview-heading,html[data-theme="dark"] .preview-logo,html[data-theme="dark"] .stat-card strong,html[data-theme="dark"] .feature-card h3,html[data-theme="dark"] .process-card h3,html[data-theme="dark"] .about-box strong,html[data-theme="dark"] .about-point,html[data-theme="dark"] .register-field label{color:var(--dark)}
html[data-theme="dark"] .feature-card p,html[data-theme="dark"] .process-card p,html[data-theme="dark"] .trust-text,html[data-theme="dark"] .about-content>p,html[data-theme="dark"] .stat-card small{color:var(--muted)}
html[data-theme="dark"] .feature-card,html[data-theme="dark"] .process-card,html[data-theme="dark"] .stat-card,html[data-theme="dark"] .about-box{border-color:var(--border)}
/* Admin workspace */
.workspace-layout{max-width:1470px;margin:24px auto 58px;display:grid;grid-template-columns:268px minmax(0,1fr);gap:22px;padding:0 24px;align-items:start}.workspace-sidebar{position:sticky;top:98px;min-height:calc(100vh - 120px);padding:18px;background:var(--surface);border:1px solid var(--border);border-radius:17px;display:flex;flex-direction:column;gap:13px}.ws-heading{display:flex;align-items:center;gap:11px;border-bottom:1px solid var(--border);padding-bottom:15px}.ws-heading strong{font-size:14px}.ws-heading small{font-size:11px;color:var(--muted);display:block;margin-top:3px}.ws-mark{display:grid;place-items:center;background:var(--primary);color:#fff;border-radius:12px;width:38px;height:38px;font-weight:800}.ws-dashboard,.ws-menu summary,.ws-children a{display:block;padding:10px 12px;border-radius:9px;font-size:13px;font-weight:600;cursor:pointer}.ws-dashboard:hover,.ws-menu summary:hover,.ws-children a:hover{background:var(--surface-alt)}.ws-dashboard.active,.ws-children a.active{background:rgba(110,97,240,.12);color:var(--primary)}.ws-module{margin-top:3px}.ws-module-title{text-transform:uppercase;color:var(--muted);letter-spacing:.11em;font-size:10px;font-weight:800;padding:6px 12px}.ws-menu summary{list-style:none;display:flex;justify-content:space-between}.ws-menu summary::-webkit-details-marker{display:none}.ws-chevron{color:var(--muted)}.ws-children{padding-left:13px}.ws-children a{font-weight:500;color:var(--text);padding:9px 11px}.ws-foot{margin-top:auto;border-top:1px solid var(--border);padding:13px 8px 0;color:var(--muted);font-size:11px}.ws-foot strong{font-size:13px;display:block;color:var(--dark);margin:4px 0}.ws-signout{border:0;background:none;color:var(--primary);font-size:12px;font-weight:700;cursor:pointer;padding:8px 0}.ws-empty{padding:10px;font-size:12px;color:var(--muted)}.workspace-content{min-width:0}.ws-intro{display:flex;justify-content:space-between;gap:20px;align-items:center;margin:24px 0}.ws-intro small,.authority-head small{font-size:10px;letter-spacing:.14em;color:var(--primary);font-weight:800}.ws-intro h1,.authority-head h1{font-size:30px;letter-spacing:-.8px;margin:5px 0}.ws-intro p,.authority-head p{color:var(--muted);font-size:13px}.ws-pill{background:var(--surface);border:1px solid var(--border);padding:9px 13px;border-radius:999px;font-size:12px;white-space:nowrap}.ws-card{background:var(--surface);border:1px solid var(--border);border-radius:17px;padding:24px;margin-bottom:18px}.ws-card h2{font-size:18px;margin-bottom:10px}.ws-card>p,.ws-card p{color:var(--muted);line-height:1.7;font-size:13px}.ws-stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:13px;margin-top:25px}.ws-stats div{background:var(--surface-alt);border:1px solid var(--border);border-radius:13px;padding:17px}.ws-stats strong{display:block;font-size:29px}.ws-stats small{color:var(--muted);font-size:11px}.ws-quick{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:10px}.ws-quick a{display:flex;justify-content:space-between;border:1px solid var(--border);border-radius:10px;padding:13px;font-size:13px}.ws-quick a:hover{color:var(--primary);background:var(--surface-alt)}.ws-placeholder{text-align:center;padding:65px 24px}.ws-placeholder-icon{font-size:46px;color:var(--primary);margin-bottom:12px}.ws-placeholder p{max-width:490px;margin:10px auto 22px}
/* Authority controls */
.authority-wrap{width:min(1220px,calc(100% - 36px));margin:35px auto 70px}.authority-head{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:25px}.authority-lines a{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:15px 0;border-bottom:1px solid var(--border);font-size:13px}.authority-lines a:last-child{border-bottom:0}.authority-lines a>span:last-child{color:var(--primary)}.authority-lines small{color:var(--muted)}.authority-form,.authority-edit{display:grid;grid-template-columns:repeat(4,minmax(0,1fr)) auto;gap:9px;align-items:center}.authority-edit{grid-template-columns:repeat(4,minmax(0,1fr)) 115px auto;padding:14px 0}.authority-form>.btn,.authority-edit>.btn{white-space:nowrap}.editor-item{border:1px solid var(--border);border-radius:11px;margin:10px 0;padding:9px 13px}.editor-item summary{cursor:pointer;display:flex;justify-content:space-between;gap:9px;font-size:13px;padding:5px 0}.editor-item summary span{font-size:11px;color:var(--muted)}.editor-nested{margin:10px 0 10px 17px}.access-module{border:1px solid var(--border);border-radius:12px;padding:16px;margin:13px 0}.access-module>strong{font-size:16px}.access-module>label{margin-left:15px}.access-module label,.access-menu label,.access-child label{font-size:12px;display:inline-flex;align-items:center;gap:7px}.access-module input[type="checkbox"]{width:16px;height:16px;accent-color:var(--primary)}.access-module select{width:auto;min-width:120px;margin-left:15px}.access-menu{border-top:1px solid var(--border);padding:12px 0 4px 15px;margin-top:10px;font-size:13px}.access-menu>span{font-weight:700}.access-child{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:7px 0 7px 19px;color:var(--text);font-size:12px}.access-save{border-top:1px solid var(--border);padding-top:20px;display:flex;justify-content:space-between;align-items:center;gap:15px}.access-save span{font-size:12px;color:var(--muted)}
@media(max-width:950px){.workspace-layout{grid-template-columns:220px minmax(0,1fr);gap:13px;padding:0 12px}.authority-form,.authority-edit{grid-template-columns:repeat(2,minmax(0,1fr))}.authority-form button,.authority-edit button{grid-column:span 2}}
@media(max-width:680px){.workspace-layout{display:block}.workspace-sidebar{position:static;min-height:auto;margin-bottom:18px}.workspace-content .ws-intro,.authority-head{align-items:flex-start;flex-direction:column}.ws-intro h1,.authority-head h1{font-size:25px}.ws-card{padding:18px}.ws-stats{gap:7px}.ws-stats div{padding:10px}.ws-stats strong{font-size:24px}.authority-form,.authority-edit{grid-template-columns:1fr}.authority-form button,.authority-edit button{grid-column:auto}.access-child{padding-left:7px}}
</style>
